# Write only explicit user-selected files; replacement is atomic in the same directory.
import json
import os
import tempfile
from pathlib import Path

def write_json(path, value):
    target = Path(path)
    handle, temporary = tempfile.mkstemp(prefix='.'+target.name+'.',suffix='.tmp',dir=target.parent)
    try:
        with os.fdopen(handle,'w',encoding='utf-8') as stream:
            json.dump(value,stream,ensure_ascii=False,indent=2)
            stream.write('\n')
        os.replace(temporary,target)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)

def read_json(path):
    if Path(path).stat().st_size > 2*1024*1024:
        raise ValueError('Project data must be at most 2 MB.')
    return json.loads(Path(path).read_text(encoding='utf-8-sig'))

