STORY = json.loads(STORY_JSON)
INVENTORY = {'note','compass','inscription','brass_key','garden_key'}

def escape_new(app):
    if getattr(app,'dirty',False) and not messagebox.askyesno('Escape Room','Discard unsaved progress?',parent=app.Form1):
        return
    app.state = {'type':'tkvf-escape','version':1,'room':'foyer','inventory':[],'solved':[],'ending':'','moves':0}
    app.dirty = True; app.notice = 'Explore, collect clues and solve the two puzzles.'; escape_draw(app)

def escape_validate(value):
    if not isinstance(value,dict) or set(value) != {'type','version','room','inventory','solved','ending','moves'} or value['type']!='tkvf-escape' or value['version']!=1 or value['room'] not in STORY:
        raise ValueError('Invalid Escape Room v1 save.')
    for key,allowed in (('inventory',INVENTORY),('solved',{'box','panel'})):
        items = value[key]
        if not isinstance(items,list) or not all(isinstance(x,str) and x in allowed for x in items) or len(set(items))!=len(items):
            raise ValueError('Invalid inventory or puzzle state.')
    if value['ending'] not in ('','solo','rescued') or type(value['moves']) is not int or not 0<=value['moves']<=100000:
        raise ValueError('Invalid ending or move count.')
    items=set(value['inventory']);solved=set(value['solved'])
    if ('brass_key' in items)!=('box' in solved) or ('garden_key' in items)!=('panel' in solved):
        raise ValueError('Puzzle rewards and solved state disagree.')
    if value['room'] in ('workshop','garden') and 'brass_key' not in items or value['room']=='garden' and 'garden_key' not in items:
        raise ValueError('Missing room key.')
    if value['ending'] and value['room']!='garden' or value['ending']=='rescued' and 'compass' not in items:
        raise ValueError('Invalid ending location or missing compass.')
    return json.loads(json.dumps(value))

def escape_actions(state):
    if state['ending']:
        return []
    room = STORY[state['room']]; result = []
    for item in room['items']:
        if item not in state['inventory']:
            result.append(('take',item,'Inspect / take '+item))
    for destination in room['exits']:
        result.append(('go',destination,'Go to '+STORY[destination]['title']))
    if 'puzzle' in room and room['puzzle']['id'] not in state['solved']:
        result.append(('solve','',room['puzzle']['question']))
    if state['room']=='garden':
        result.extend([('end','solo','Leave alone'),('end','rescued','Guide the companion with the compass')])
    return result

def escape_apply(state, action, argument, answer=''):
    state = escape_validate(state)
    if state['ending'] or (action,argument) not in [(a,b) for a,b,label in escape_actions(state)]:
        raise ValueError('That action is not available.')
    room = STORY[state['room']]; notice = ''
    if action=='take':
        state['inventory'].append(argument); notice=room['items'][argument]
    elif action=='go':
        key = room['exits'][argument]['key']
        if key and key not in state['inventory']:
            return state,'The door is locked. Find the key first.'
        state['room']=argument; notice='You enter '+STORY[argument]['title']+'.'
    elif action=='solve':
        puzzle=room['puzzle']
        if answer.strip().casefold()!=puzzle['answer'].casefold():
            return state,'The mechanism stays locked. Inspect the clues and try again.'
        state['solved'].append(puzzle['id']);state['inventory'].append(puzzle['reward']);notice='Solved! You receive '+puzzle['reward']+'.'
    elif action=='end':
        if argument=='rescued' and 'compass' not in state['inventory']:
            return state,'You need a compass to guide the companion.'
        state['ending']=argument;notice='You and your companion reach safety.' if argument=='rescued' else 'You escape alone, leaving the mystery behind.'
    state['moves']+=1
    return state,notice

def escape_draw(app):
    room=STORY[app.state['room']];app.Scene.delete('all');app.Scene.create_rectangle(20,20,920,160,fill=room['color'],outline='')
    app.Scene.create_text(470,60,text=room['title'],font=('TkDefaultFont',22,'bold'))
    app.Scene.create_text(470,115,text='Two puzzles • Three rooms • Two endings',font=('TkDefaultFont',13))
    app.Story.delete('1.0','end');app.Story.insert('1.0',room['description']+'\n\n'+app.notice)
    app.options=escape_actions(app.state);app.Actions.delete(0,'end')
    for action,argument,label in app.options:
        app.Actions.insert('end',label)
    app.Inventory.configure(text='Inventory: '+(', '.join(app.state['inventory']) or '(empty)'))
    app.Progress.configure(text=f"Moves: {app.state['moves']} | Puzzles: {len(app.state['solved'])}/2 | Ending: {app.state['ending'] or 'playing'} | "+('Unsaved' if app.dirty else 'Saved'))

def escape_act(app):
    selection=app.Actions.curselection()
    if not selection:
        return
    action,argument,label=app.options[selection[0]]
    state,notice=escape_apply(app.state,action,argument,app.Answer.get())
    app.dirty = app.dirty or state!=app.state;app.state=state;app.notice=notice;app.Answer.delete(0,'end');escape_draw(app)

def escape_file(app, opening=False):
    if opening and app.dirty and not messagebox.askyesno('Escape Room','Discard unsaved progress?',parent=app.Form1):
        return
    path=(filedialog.askopenfilename if opening else filedialog.asksaveasfilename)(parent=app.Form1,defaultextension='.json',filetypes=[('Escape save','*.json')])
    if not path:
        return
    try:
        if opening:
            state=escape_validate(read_json(path));app.state=state;app.notice='Progress restored.'
        else:
            write_json(path,escape_validate(app.state));app.notice='Progress saved.'
        app.dirty=False;escape_draw(app)
    except (OSError,ValueError,TypeError) as exc:
        messagebox.showerror('Escape Room',str(exc),parent=app.Form1)

def escape_close(app):
    if app.dirty and not messagebox.askyesno('Escape Room','Close and discard unsaved progress?',parent=app.Form1):
        return
    app.root.destroy()
